//! AUTO: read access to structure; converting into dictionary
inline py::dict GetDictionaryWithTypeInfo(const VSettingsCamera& data) {
    auto structureDict = py::dict();
    auto d = py::dict(); //local dict
    structureDict["structureDescription"] = "Settings for camera like perspective, marker tracking, clipping plane, etc. Note that some options may also be found in openGL settings.";
    d = py::dict(); //reset local dict
    d["itemIdentifier"] = std::string(""); //identifier for item
    d["value"] = EPyUtils::ToPythonMember(data.cameraPosition);
    d["type"] = "VectorFloat";
    d["size"] = std::vector<int>{3};
    d["description"] = "if modelCentricView=True: offset to camera position in model view (and, if used, relative to tracked marker - instead of a tracked marker position, you could also just change the camera position in camera-centric views); camera rotation follows modelRotation in renderState";
    structureDict["cameraPosition"] = d;

    d = py::dict(); //reset local dict
    d["itemIdentifier"] = std::string(""); //identifier for item
    d["value"] = data.clippingPlaneDistance;
    d["type"] = "float";
    d["size"] = std::vector<int>{1};
    d["description"] = "distance of clipping plane on normal vector; see also clippingPlaneNormal and openGL.advanced.clippingPlaneColor";
    structureDict["clippingPlaneDistance"] = d;

    d = py::dict(); //reset local dict
    d["itemIdentifier"] = std::string(""); //identifier for item
    d["value"] = EPyUtils::ToPythonMember(data.clippingPlaneNormal);
    d["type"] = "VectorFloat";
    d["size"] = std::vector<int>{3};
    d["description"] = "normal vector of clipping plane, e.g. [0,0,1] to set a xy-clipping plane; the clipped half-space is in direction of the normal; use [0,0,0] to deactivate clipping plane; Note that clipping is mainly made for triangles in order to visualize hidden objects and currently it only fully clips triangles, but does not exactly cut them; see also clippingPlaneDistance and openGL.advanced.clippingPlaneColor";
    structureDict["clippingPlaneNormal"] = d;

    d = py::dict(); //reset local dict
    d["itemIdentifier"] = std::string(""); //identifier for item
    d["value"] = data.modelCentricView;
    d["type"] = "bool";
    d["size"] = std::vector<int>{1};
    d["description"] = "True: rotations and translations are applied to model, while camera stays far enough away from the model and always captures the whole model (everything is in front of camera plane); False: camera moves and rotates while model stays in physical space; only geometry in front of camera is visible; note that the behavior of trackMarker changes with modelCentricView and some features are not available in case of modelCentricView=False.";
    structureDict["modelCentricView"] = d;

    d = py::dict(); //reset local dict
    d["itemIdentifier"] = std::string(""); //identifier for item
    d["value"] = EPyUtils::ToPythonMember(data.nearFarPlaneOffset);
    d["type"] = "VectorFloat";
    d["size"] = std::vector<int>{3};
    d["description"] = "the three values are [nearPlaneOffset, farPlaneOffset, flag]; if flag=0, the offsets are ignored and computed automatically, using x = 2 * maxSceneSize * zMaxSceneFactor, setting near plane to -x and far plane to +x in case of modelCentricView=True and setting near plane to 0.01 (minimal offset to eye point) and far plane to +x if modelCentricView=False; if flag=1, the near and far plane values are just overwritten; note that positive values for near plane make objects in front of the camera invisible while negative values make objects behind the camera plane visible; in case of camera-centric view, the eyepoint can be shifted backwards using cameraPosition accordingly.";
    structureDict["nearFarPlaneOffset"] = d;

    d = py::dict(); //reset local dict
    d["itemIdentifier"] = std::string(""); //identifier for item
    d["value"] = data.perspective;
    d["type"] = "UFloat";
    d["size"] = std::vector<int>{1};
    d["description"] = "parameter prescribes amount of perspective (0=no perspective=orthographic projection; positive values increase perspective; feasible values are 0.001 (little perspective) ... 1 (extreme: 5), where larger values are possible but should be used with care; NOTE that the relation to the common field of view (FOV) angle alpha, with alpha=90°, is given by perspective = tan(alpha/2) = 1; mouse coordinates (F3) can not be shown with perspective>0";
    structureDict["perspective"] = d;

    d = py::dict(); //reset local dict
    d["itemIdentifier"] = std::string(""); //identifier for item
    d["value"] = data.trackMarker;
    d["type"] = "Int";
    d["size"] = std::vector<int>{1};
    d["description"] = "if valid marker index is provided and marker provides position (and orientation), the centerpoint of the scene follows the marker (and orientation); depends on trackMarkerPosition and trackMarkerOrientation; by default, only position is tracked";
    structureDict["trackMarker"] = d;

    d = py::dict(); //reset local dict
    d["itemIdentifier"] = std::string(""); //identifier for item
    d["value"] = data.trackMarkerMbsNumber;
    d["type"] = "Index";
    d["size"] = std::vector<int>{1};
    d["description"] = "number of main system which is used to track marker; if only 1 mbs is in the SystemContainer, use 0; if there are several mbs, it needs to specify the number";
    structureDict["trackMarkerMbsNumber"] = d;

    d = py::dict(); //reset local dict
    d["itemIdentifier"] = std::string(""); //identifier for item
    d["value"] = EPyUtils::ToPythonMember(data.trackMarkerOrientation);
    d["type"] = "VectorFloat";
    d["size"] = std::vector<int>{3};
    d["description"] = "choose which orientation axes (x,y,z) are tracked; currently can only be all zero or all one";
    structureDict["trackMarkerOrientation"] = d;

    d = py::dict(); //reset local dict
    d["itemIdentifier"] = std::string(""); //identifier for item
    d["value"] = EPyUtils::ToPythonMember(data.trackMarkerPosition);
    d["type"] = "VectorFloat";
    d["size"] = std::vector<int>{3};
    d["description"] = "choose which coordinates or marker are tracked (x,y,z)";
    structureDict["trackMarkerPosition"] = d;

    d = py::dict(); //reset local dict
    d["itemIdentifier"] = std::string(""); //identifier for item
    d["value"] = data.useRaytracer;
    d["type"] = "bool";
    d["size"] = std::vector<int>{1};
    d["description"] = "True: use (software) raytracer for this view; False: use standard OpenGL renderer";
    structureDict["useRaytracer"] = d;

    return structureDict;
}

