    d = py::dict(); //reset local dict
    d["itemIdentifier"] = std::string(""); //identifier for item
    d["value"] = data.materialShininess;
    d["type"] = "float";
    d["size"] = std::vector<int>{1};
    d["description"] = "shininess of material";
    structureDict["materialShininess"] = d;

    d = py::dict(); //reset local dict
    d["itemIdentifier"] = std::string(""); //identifier for item
    d["value"] = EPyUtils::ToPythonMember(data.materialSpecular);
    d["type"] = "VectorFloat";
    d["size"] = std::vector<int>{4};
    d["description"] = "RGBA specular color of material";
    structureDict["materialSpecular"] = d;

    d = py::dict(); //reset local dict
    d["itemIdentifier"] = std::string(""); //identifier for item
    d["value"] = data.multiSampling;
    d["type"] = "PInt";
    d["size"] = std::vector<int>{1};
    d["description"] = "NOTE: this parameter must be set before starting renderer; later changes are not affecting visualization; multi sampling turned off (<=1) or turned on to given values (2, 3, 4, 8 or 16); increases the graphics buffers and might crash due to graphics card memory limitations; only works if supported by hardware; if it does not work, try to change 3D graphics hardware settings!";
