//! AUTO: read access to structure; converting into dictionary
inline py::dict GetDictionaryWithTypeInfo(const VSettingsInteractive& data) {
    auto structureDict = py::dict();
    auto d = py::dict(); //local dict
    structureDict["structureDescription"] = "Functionality to interact with render window; includes special rotation and zoom factors, item-highlighting, marker tracking, item selection and keyPressUserFunction.";
    structureDict["advanced"] = GetDictionaryWithTypeInfo(data.advanced);
    d = py::dict(); //reset local dict
    d["itemIdentifier"] = std::string(""); //identifier for item
    d["value"] = data.autoRotateModelView;
    d["type"] = "bool";
    d["size"] = std::vector<int>{1};
    d["description"] = "True: rotate model view with autorotation";
    structureDict["autoRotateModelView"] = d;

    d = py::dict(); //reset local dict
    d["itemIdentifier"] = std::string(""); //identifier for item
    d["value"] = EPyUtils::ToPythonMember(data.autoRotationVelocity);
    d["type"] = "VectorFloat";
    d["size"] = std::vector<int>{3};
    d["description"] = "Angular velocity vector for auto-rotation of scene (only visualization view is rotated, not the model itself!)";
    structureDict["autoRotationVelocity"] = d;

    d = py::dict(); //reset local dict
    d["itemIdentifier"] = std::string(""); //identifier for item
    d["value"] = data.highlightItemIndex;
    d["type"] = "Int";
    d["size"] = std::vector<int>{1};
    d["description"] = "index of item that shall be highlighted (e.g., to find item which cauess problems); if set -1, no item is highlighted";
    structureDict["highlightItemIndex"] = d;

    d = py::dict(); //reset local dict
    d["itemIdentifier"] = std::string(""); //identifier for item
    d["value"] = data.highlightItemType;
    d["type"] = "ItemType";
    d["size"] = std::vector<int>{1};
    d["description"] = "item type (Node, Object, ...) that shall be highlighted (e.g., to find item which cauess problems)";
    structureDict["highlightItemType"] = d;

    d = py::dict(); //reset local dict
    d["itemIdentifier"] = std::string(""); //identifier for item
    d["value"] = data.highlightMbsNumber;
    d["type"] = "UInt";
    d["size"] = std::vector<int>{1};
    d["description"] = "index of main system (mbs) for which the item shall be highlighted; number is related to the ID in SystemContainer (first mbs = 0, second = 1, ...)";
    structureDict["highlightMbsNumber"] = d;

    d = py::dict(); //reset local dict
    d["itemIdentifier"] = std::string(""); //identifier for item
    d["value"] = data.ignoreKeys;
    d["type"] = "bool";
    d["size"] = std::vector<int>{1};
    d["description"] = "True: ignore keyboard input except escape and 'F2' keys; used for interactive mode, e.g., to perform kinematic analysis; This flag can be switched with key 'F2'; if ignoreKeys=True, then keyPressUserFunction can be used!";
    structureDict["ignoreKeys"] = d;

    d = py::dict(); //reset local dict
    d["itemIdentifier"] = std::string(""); //identifier for item
    d["value"] = data.logMouseCoordinates;
    d["type"] = "bool";
    d["size"] = std::vector<int>{1};
    d["description"] = "True: if showMouseCoordinates=True, also log mouse coordinates (transformed to model coordinates); only works for axis-aligned ortho-projections and shows the coordinates of the current plane";
    structureDict["logMouseCoordinates"] = d;

    d = py::dict(); //reset local dict
    d["itemIdentifier"] = std::string(""); //identifier for item
    d["value"] = data.useJoystickInput;
    d["type"] = "bool";
    d["size"] = std::vector<int>{1};
    d["description"] = "True: read joystick input (use 6-axis joystick with lowest ID found when starting renderer window) and interpret as (x,y,z) position and (rotx, roty, rotz) rotation: as available from 3Dconnexion space mouse and maybe others as well; set to False, if external joystick makes problems ...";
    structureDict["useJoystickInput"] = d;

    return structureDict;
}

